package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/pools")
@Validated
public class PoolController {

    /**
     * What the screen is told about a pool: its name, the crew it is (null for a pool of its own), and its
     * members in the order they were added, a crew's pool's being the crew's lead and members.
     */
    public record PoolView(long id, String name, Long crewId, List<MemberView> members) {

        static PoolView of(PoolService.PoolWithMembers pool) {
            return new PoolView(pool.pool().getId(), pool.pool().getName(), pool.pool().getCrewId(),
                    pool.members().stream().map(MemberView::of).toList());
        }
    }

    /**
     * A pool's member: the person or the member pool (the other null), its name, and its share percent with
     * two decimals, and the dates the membership is in force between (null: open-ended).
     */
    public record MemberView(Long personId, Long poolId, String name, String share, LocalDate from, LocalDate to) {

        static MemberView of(PoolService.Member member) {
            return new MemberView(member.member().getPersonId(), member.member().getMemberPoolId(), member.name(),
                    member.member().getShare().toPlainString(), member.member().getFromDate(),
                    member.member().getToDate());
        }
    }

    /** A pool as entered on the form: a name, trimmed by the service. */
    public record PoolForm(@NotNull @Size(max = 100) String name) {
    }

    /**
     * A member as entered on the pool's row: a person or another pool (exactly one of them) and a share
     * percent with up to two decimals, and optionally the dates the membership is in force between.
     */
    public record MemberForm(Long personId, Long poolId, @NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String share,
            LocalDate from, LocalDate to) {
    }

    private final PoolService service;

    public PoolController(PoolService service) {
        this.service = service;
    }

    /** The sheet's pools in the order they were added. */
    @GetMapping
    public List<PoolView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return service.list(sheetId).stream().map(PoolView::of).toList();
    }

    /** Add a pool to the sheet. */
    @PostMapping
    public PoolView add(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PoolForm form) {
        return PoolView.of(service.add(sheetId, SignedIn.name(user), form.name()));
    }

    /** Add a member to a pool: the pool as it is then. */
    @PostMapping("/{poolId}/members")
    public PoolView addMember(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long poolId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid MemberForm form) {
        if ((form.personId() == null) == (form.poolId() == null)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Choose a person or a pool.");
        }
        if (form.poolId() != null) {
            return PoolView.of(service.addPoolMember(sheetId, SignedIn.name(user), poolId, form.poolId(),
                    new BigDecimal(form.share()), form.from(), form.to()));
        }
        return PoolView.of(service.addMember(sheetId, SignedIn.name(user), poolId, form.personId(),
                new BigDecimal(form.share()), form.from(), form.to()));
    }

    /** Another user added the same name or member between the check and the write: the unique index refuses it. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void taken() {
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * A pool on a sheet: a name, trimmed and on the sheet at most once, never a crew's but its own crew's. A
 * crew's pool names the crew; its members are the crew's, not stored.
 */
@Entity
@Table(name = "pool")
public class Pool {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(nullable = false)
    private String name;

    @Column(name = "crew_id")
    private Long crewId;

    protected Pool() {
    }

    public Pool(String sheetId, String name) {
        this.sheetId = sheetId;
        this.name = name;
    }

    /** A crew's pool, under the crew's name. */
    public static Pool ofCrew(String sheetId, String name, Long crewId) {
        Pool pool = new Pool(sheetId, name);
        pool.crewId = crewId;
        return pool;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    /** The crew this pool is; null for a pool of its own. */
    public Long getCrewId() {
        return crewId;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A pool's member: a person on the sheet, in the pool at most once, or another pool (a member of at most
 * one pool), with a share percent and an optional from-date and to-date it is in force between. Exactly
 * one of the person and the member pool is set.
 */
@Entity
@Table(name = "pool_member")
public class PoolMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "pool_id", nullable = false)
    private Long poolId;

    @Column(name = "person_id")
    private Long personId;

    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected PoolMember() {
    }

    public PoolMember(Long poolId, Long personId, BigDecimal share) {
        this.poolId = poolId;
        this.personId = personId;
        this.share = share;
    }

    /** A pool as a member of another pool, with a share percent. */
    public static PoolMember ofPool(Long poolId, Long memberPoolId, BigDecimal share) {
        PoolMember member = new PoolMember(poolId, null, share);
        member.memberPoolId = memberPoolId;
        return member;
    }

    public Long getId() {
        return id;
    }

    public Long getPoolId() {
        return poolId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** The pool that is the member; null when the member is a person. */
    public Long getMemberPoolId() {
        return memberPoolId;
    }

    public BigDecimal getShare() {
        return share;
    }

    /** The first day the membership is in force; null when it has no start. */
    public LocalDate getFromDate() {
        return fromDate;
    }

    /** The last day the membership is in force; null when it has no end. */
    public LocalDate getToDate() {
        return toDate;
    }

    /** Set the days the membership is in force between, either end optional. */
    public PoolMember during(LocalDate from, LocalDate to) {
        this.fromDate = from;
        this.toDate = to;
        return this;
    }

    /** Move the membership to another person on the sheet, its share kept. */
    public void moveTo(Long personId) {
        this.personId = personId;
    }

    /** Add a share to the member's own. */
    public void addShare(BigDecimal more) {
        this.share = share.add(more);
    }
}
